// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // the contract pays out to msg.sender (this test contract), so it must accept ETH
    receive() external payable {}

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 f, uint256 v) public {
        // admissible domain: the contract is funded with f wei, owner withdraws v <= f
        f = bound(f, 0, type(uint256).max / 2);
        v = bound(v, 0, f);
        vm.deal(address(c), f);

        // owner is this test contract (deployer), it can receive the transfer
        c.withdraw(v);

        // general rule: only the requested value v leaves the contract
        assertTrue(address(c).balance == f - v);
    }
}
